WITH ranked AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY event_id ORDER BY received_ts_ms, ingest_id) AS rn
  FROM raw_events
), clean AS (
  SELECT * FROM ranked WHERE rn = 1
)
SELECT ingest_id, event_id, user_id, attempt_id, event_name, event_ts_ms, received_ts_ms FROM clean ORDER BY event_id;
